namespace sv_7c460ea4970a42fe81b372f29dc7c461.Models;

// Immutable records for submission
public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

// Service contract
public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

// Mutable form models for two-way binding
public class PersonalInfoModel
{
    public string FullName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string Address { get; set; } = "";

    public PersonalInfo ToRecord() => new(FullName, Email, Phone, Address);
}

public class WorkEntryModel
{
    public string Company { get; set; } = "";
    public string Title { get; set; } = "";
    public DateTime? StartDate { get; set; }
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = "";

    public WorkEntry ToRecord() => new(Company, Title, StartDate!.Value, IsCurrent ? null : EndDate, Description);
}

public class ReferenceModel
{
    public string Name { get; set; } = "";
    public string Relationship { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";

    public Reference ToRecord() => new(Name, Relationship, Email, Phone);
}

using sv_7c460ea4970a42fe81b372f29dc7c461.Models;

namespace sv_7c460ea4970a42fe81b372f29dc7c461.Services;

public class ApplicationService : IApplicationService
{
    private static int _nextId = 1000;

    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1500); // Simulate network call
        return Interlocked.Increment(ref _nextId);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(500); // Simulate validation
        return !string.IsNullOrWhiteSpace(email)
            && email.Contains('@')
            && email.Contains('.');
    }
}

@namespace sv_7c460ea4970a42fe81b372f29dc7c461.Components.JobApplication

<nav class="d-flex justify-content-between mb-4 position-relative">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var isCompleted = CompletedSteps.Contains(stepIndex);
        var isCurrent = stepIndex == CurrentStep;
        var isFuture = stepIndex > CurrentStep && !isCompleted;

        <div class="text-center flex-fill step-item @(isCurrent ? "fw-bold" : "")"
             style="cursor: @(isCompleted ? "pointer" : "default"); opacity: @(isFuture ? "0.4" : "1");"
             @onclick="() => OnStepClick(stepIndex, isCompleted)">
            <div class="mx-auto mb-1 rounded-circle d-flex align-items-center justify-content-center @StepCircleClass(isCurrent, isCompleted)"
                 style="width: 36px; height: 36px;">
                @if (isCompleted)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <small>@StepNames[stepIndex]</small>
        </div>
    }
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepSelected { get; set; }

    private async Task OnStepClick(int step, bool isCompleted)
    {
        if (isCompleted)
            await OnStepSelected.InvokeAsync(step);
    }

    private string StepCircleClass(bool isCurrent, bool isCompleted)
    {
        if (isCurrent) return "bg-primary text-white";
        if (isCompleted) return "bg-success text-white";
        return "bg-light border";
    }
}

@namespace sv_7c460ea4970a42fe81b372f29dc7c461.Components.JobApplication
@using sv_7c460ea4970a42fe81b372f29dc7c461.Models

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h6 class="card-title mb-0">Reference @Index</h6>
            @if (CanRemove)
