@page "/apply"
@rendermode InteractiveServer

@using sv_7c460ea4970a42fe81b372f29dc7c461.Components.JobApplication
@using sv_7c460ea4970a42fe81b372f29dc7c461.Models

@inject IApplicationService AppService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="_currentStep"
                   CompletedSteps="_completedSteps"
                   StepNames="_stepNames"
                   OnStepSelected="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Model="_personal"
                              ValidateEmail="AppService.ValidateEmailAsync"
                              OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="_workEntries"
                             OnNext="NextStep"
                             OnBack="PrevStep" />
            break;
        case 2:
            <ReferencesStep References="_references"
                            OnNext="NextStep"
                            OnBack="PrevStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             CoverLetterChanged="val => _coverLetter = val"
                             OnNext="NextStep"
                             OnBack="PrevStep" />
            break;
        case 4:
            <ReviewStep Personal="_personal"
                        WorkEntries="_workEntries"
                        References="_references"
                        CoverLetter="@_coverLetter"
                        SubmittedId="_submittedId"
                        OnEdit="GoToStep"
                        OnBack="PrevStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private readonly HashSet<int> _completedSteps = new();
    private int? _submittedId;
    private string _coverLetter = "";

    private readonly List<string> _stepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private readonly PersonalInfoModel _personal = new();
    private readonly List<WorkEntryModel> _workEntries = new() { new() };
    private readonly List<ReferenceModel> _references = new() { new(), new() };

    private void NextStep()
    {
        _completedSteps.Add(_currentStep);
        if (_currentStep < _stepNames.Count - 1)
            _currentStep++;
    }

    private void PrevStep()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private async Task SubmitApplication()
    {
        var application = new JobApplication(
            _personal.ToRecord(),
            new WorkHistory(_workEntries.Select(e => e.ToRecord()).ToList()),
            _references.Select(r => r.ToRecord()).ToList(),
            _coverLetter
        );

        _submittedId = await AppService.SubmitApplicationAsync(application);
        _completedSteps.Add(_currentStep);
    }
}

